    if not armature_obj.type == 'ARMATURE':
        return

    # Get bone data array (available in Blender 5.x via prop_array or direct access)
    try:
        bone_data = armature_obj.bone_data
    except AttributeError:
        return

    for bone in bone_data.bones:
        if not bone.visible:
            continue

        # Apply the transformation matrix to each bone's transform component directly
        # In Blender 5.x, we can access and modify the transform via prop_array or internal API
        try:
            # Access the transform property (rotation + scale) of the bone
            if hasattr(bone, 'transform'):
                original_transform = bone.transform.copy()
                new_transform = matrix @ original_transform

                # Set the updated transform back to the bone data
                bone.data['bone']._data[0].set(new_transform.to_4x4())  # Direct access may vary by version

            else:
                # Fallback for older/newer versions using set_bone_data_flag if needed
                armature_obj.bones[bone.name].transform = new_transform

        except Exception as e:
            print(f"Error applying transform to bone {bone.name}: {e}")

    # Enable axis display for all bones in the active object's collection
    bpy.context.scene.view_layer.objects.active = armature_obj
