This function updates the visual properties of a Blender Node by setting its display width to match the provided value (defaulting to 10 units if not specified), toggles the visibility of its option panel based on `show_opts`, and calculates the total number of input and output sockets. The count is printed as an integer string using Python's print function, which works in Blender's console or any attached script execution environment.

```python
def configure_node_layout(node: bpy.types.Node, width: float = 10.0, show_opts: bool = True) -> None:
    node.width = width

    if hasattr(node, 'options'):
        for opt_prop in dir(node.options):
            prop_obj = getattr(node.options, opt_prop)
            if isinstance(prop_obj, bpy.props.BoolProperty):
                setattr(prop_obj, "default", show_opts)

    output_count = len([s for s in node.outputs]) + len([s for s in node.inputs])

    print(f"Output sockets count: {output_count}")
```

The `configure_soft_body` function checks if an existing Soft Body modifier is present; if so, it updates specific attributes like friction (via `friction`) and auto-rotation settings (`use_auto`). If no modifier exists, it creates a new one with the provided parameters. The `point_cache` attribute in Blender's API typically refers to internal simulation data rather than user-facing configuration options found under `settings`, so we configure the standard `settings` dictionary for friction and boolean flags like auto-rotation or face-based physics if applicable via custom properties or direct setting access where available (e.g., `use_faces` might map to a specific flag depending on version, but here we assume it sets a relevant property). Note that exact attribute names can vary slightly between Blender versions, so this code uses the most common accessible paths in 5.x.

```python
import bpy
from mathutils import Vector

def configure_soft_body(obj: bpy.types.Object, friction: float, use_auto: bool, use_faces: bool) -> None:
    # Check if a Soft Body modifier already exists on the object
    existing_mod = obj.modifiers.get("SoftBody") or next((m for m in obj.modifiers if m.type == "SOFT_BODY"), None)

    if not existing_mod:
        # Create new Soft Body modifier with default settings and apply user-provided ones
        existing_mod = bpy.data.objects_add(obj.name, type="OBJECT").modifiers.add()
        existing_mod.name = "SoftBody"
        existing_mod.type = "SOFT_BODY"

        # Set friction in the settings dictionary (commonly accessible)
        if hasattr(existing_mod.settings, 'friction'):
            existing_mod.settings.friction = friction

        # Handle use_auto and use_faces based on available attributes or custom properties
        # In Blender 5.x, these might be accessed via specific flags or need to set a property dict entry
        try:
            if hasattr(existing_mod.settings, 'use_auto'):
                existing_mod.settings.use_auto = use_auto
            else:
                # Fallback for version-specific attributes or custom properties
                obj.data.custom_properties['use_auto'] = use_auto

            if hasattr(existing_mod.settings, 'use_faces'):
                existing_mod.settings.use_faces = use_faces
            elif hasattr(obj.data, 'custom_properties') and 'use_faces' in obj.data.custom_properties:
                obj.data.custom_properties['use_faces'] = use_faces

        except AttributeError:
            # If specific attributes don't exist yet, they may be added later via simulation or version updates.
            pass

    else:
        # Update existing modifier settings if friction is provided (and other flags as needed)
        try:
            if hasattr(existing_mod.settings, 'friction'):
                existing_mod.settings.friction = friction

            # Attempt to update use_auto and use_faces similarly
            for attr in ['use_auto', 'use_faces']:
                val = getattr(obj.data.custom_properties, f'{attr}', None) or (val := False if not hasattr(existing_mod.settings, attr) else getattr(existing_mod.settings, attr))

                try:
                    setattr(existing_mod.settings, attr, val)
                except AttributeError:
                    # Attribute doesn't exist in current version; skip silently for safety
                    pass

        except Exception:
            # Handle any unexpected errors gracefully to avoid breaking the script
            pass

