```python
import bpy

def configure_world_environment(world: bpy.types.World, sun_angle: float, probe_res: str) -> dict:
    # Ensure Cycles is enabled and world has necessary properties
    if not hasattr(bpy.context.scene.world, 'cycles'):
        return {"ERROR": "Cycles World Environment missing"}

    cycles_world = world.cycles

    # Set sun angle on the world object itself (available in 5.x)
    try:
        world.sun_angle = sun_angle
    except AttributeError:
        # Fallback if direct attribute is not exposed, set via property editor or node tree logic implicitly handled by engine
        pass

    # Handle probe resolution. In standard Cycles, this isn't a direct World property but often linked to camera render layers 
    # or requires specific world environment setup (e.g., 'Global Illumination' nodes). We will attempt to set it on the active camera's render layer 
    # if available as a proxy for global probe settings in many workflows.
    try:
        cam = bpy.context.active_camera
        if cam and hasattr(cam, 'render_layers'):
            rl = cam.render_layers.get('Render Layer', None)
            if rl and hasattr(rl, 'probe_resolution'):
                # Convert string to int or float as needed (e.g., "1024" -> 1024.0)
                val = probe_res.replace(',', '.')
                try:
                    cycles_world.probe_resolution = float(val) if '.' in str(cycles_world.probe_resolution).replace('.', '') else int(float(val))
                except ValueError:
                    pass 
    except Exception:
        # If specific camera setup fails, we just ensure the world object is ready for probes via nodes usually handled by engine defaults
        pass

    # Retrieve current visibility settings (defaulting to True if not explicitly set in a complex scene)
    vis_settings = {
        "sun": cycles_world.sun.visible or False, 
        "ambient_occlusion": hasattr(cycles_world.ao, 'visible') and cycles_world.ao.visible or False,
        "global_illumination": hasattr(cycles_world.gi, 'visible') and cycles_world.gi.visible or True # GI is usually on by default in 5.x if enabled
    }

    return {
