def configure_node_socket_gizmos(node_tree: bpy.types.NodeTree):
    for node in node_tree.nodes.values():
        # Iterate through all input sockets of a node (excluding output sockets usually, but checking both covers cases)
        if hasattr(node, 'inputs') and len(node.inputs) > 0:
            for inp_socket in node.inputs:
                if hasattr(inp_socket, 'is_icon_visible'):
