```python
import bpy

def manage_constraints(active_obj: bpy.types.Object, target_objs: list[bpy.types.Object], constraint_name: str):
    # 1. Set active object in context
    bpy.context.view_layer.objects.active = active_obj
    bpy.ops.object.select_all(action='DESELECT')
    bpy.ops.object.select_active(add=True)

    # Get the original constraint instance from the active object
    orig_constraint = None
    for c in active_obj.constraints:
        if hasattr(c, 'name') and c.name == constraint_name:
            orig_constraint = c
            break

    if not orig_constraint or type(orig_constraint).__name__ != "Constraint":
        raise ValueError(f"Could not find a valid Constraint named '{constraint_name}' on {active_obj}")

    # 2. Duplicate the specific constraint instance (not just copy properties)
    new_constraint = bpy.data.constraints.new(type=type(orig_constraint))
    active_obj.constraints.add(1, new_constraint)

    # Copy data from original to duplicate
    for attr in dir(new_constraint):
        if not attr.startswith('_'):
            try:
                setattr(new_constraint, attr, getattr(orig_constraint, attr))
            except AttributeError:
                continue

    # 3. Reset distance limit on the modified constraint (and thus propagated)
    new_constraint.distance_limit = -1000.0 

    # Apply changes to active object immediately so it reflects in scene
    bpy.context.view_layer.update()

    # 4. Copy constraints to all target_objs
    for obj in target_objs:
        if not hasattr(obj, 'constraints'):
            continue

        found = False
        for c in obj.constraints:
            if type(c).__name__ == "Constraint" and getattr(c, 'name', '') == constraint_name:
                # Found existing instance of same name/type, update it directly to save memory/time
                new_constraint_copy = bpy.data.constraints.new(type=type(new_constraint))
                c.add(1, new_constraint_copy)

                for attr in dir(new_constraint):
                    if not attr.startswith('_'):
                        try:
                            setattr(c, attr, getattr(orig_constraint, attr))
                        except AttributeError:
                            continue

                # Ensure distance limit is reset here too as a safeguard since we are modifying the base instance logic 
                # but applying to multiple objects. Actually, per requirement "Copies... to all", usually implies creating new instances or updating existing ones with same settings.
                # Since we modified 'new_constraint' (the duplicate), and copied its data including distance_limit above:
                pass

        # If no matching constraint name found in target_objs, create one based on the template
        if not found:
            c = bpy.data.constraints.new(type=type(new_constraint))
            obj.constraints.add(1, c)

            for attr in dir(orig_constraint):
                if not attr.startswith('_'):
                    try:
                        setattr(c, attr, getattr(orig_constraint, attr))
                    except AttributeError:
                        continue

            # Explicitly set distance limit again to ensure it's reset as per step 3 logic applied universally
            c.distance_limit = -1000.0

    bpy.context.view_layer.update()
