import bpy
from bpy.props import BoolProperty, FloatProperty


class MyTextCurve(bpy.types.TextCurve):
    bold: BoolProperty(
        name="Bold",
        description="Whether to apply a bold style.",
        default=False,
    )

    underline_height: FloatProperty(
        name="Underline Height",
        description="Height of the underline relative to text height (0.0 - 0.8).",
        min=0.0,
        max=0.8,
        soft_min=0.0,
        soft_max=0.8,
    )

    def update(self):
        # Triggered when properties change to apply logic if needed externally
        pass

    @property
    def is_select_bold(self):
        return self.is_selected and bool(self.bold)

    @is_select_bold.setter
    def is_select_bold(self, value: bool):
        try:
            super().is_select_bold = value
        except RuntimeError as e:
            # This exception occurs if there is no selected text in the scene.
            # We catch it to ensure the function does not crash on invalid states.
            pass


def apply_text_style(text_curve: bpy.types.TextCurve, bold: bool, underline_h: float) -> None:
    """Applies style settings with error handling for read-only properties."""

